def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def count_up_to(X):
        if X <= 0:
            return 0
        s = str(X)
        n = len(s)
        memo = {}
        def dp(pos, started, diff, mod, tight):
            if pos == n:
                return 1 if (started and diff == 0 and mod == 0) else 0
            key = (pos, started, diff, mod, tight)
            if key in memo:
                return memo[key]
            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_started = started or (d != 0)
                if not started and d == 0:
                    new_mod = mod
                else:
                    new_mod = (mod * 10 + d) % k
                new_diff = diff
                if new_started:
                    if d % 2 == 0:
                        new_diff += 1
                    else:
                        new_diff -= 1
                total += dp(pos + 1, new_started, new_diff, new_mod, new_tight)
            memo[key] = total
            return total
        return dp(0, False, 0, 0, True)

    return count_up_to(high) - count_up_to(low - 1)

def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    base = (m - 1) % MOD
    term1 = pow(base, n, MOD)
    if n % 2 == 0:
