def count_square_permutations(n: int, s: str) -> int:
    target = [0]*10
    for ch in s:
        target[int(ch)] += 1
    max_val = 10**n - 1
    limit = int(max_val**0.5)
    count = 0
    for k in range(limit + 1):
        sq = k * k
        padded = str(sq).zfill(n)
        freq = [0]*10
        for ch in padded:
            freq[int(ch)] += 1
        if freq == target:
            count += 1
    return count

def kth_smallest_amount(coins: List[int], k: int) -> int:
    import math
    coins = list(set(coins))
    n = len(coins)

    def count_multiples(x: int) -> int:
        total = 0
        for mask in range(1, 1 << n):
            lcm = 1
            bits = 0
            for i in range(n):
                if mask & (1 << i):
                    bits += 1
                    c = coins[i]
                    g = math.gcd(lcm, c)
                    if lcm // g > x // c:
                        lcm = x + 1
                        break
                    lcm = lcm // g * c
            if lcm > x:
                continue
            cnt = x // lcm
            if bits % 2 == 1:
                total += cnt
            else:
                total -= cnt
        return total

    lo = 1
    hi = min(coins) * k
    while lo < hi:
        mid = (lo + hi) // 2
        if count_multiples(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

