def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    total_area = sum(a * b for a, b in tiles)
    if total_area < h * w:
        return False
    target = h * w
    valid_masks = []
    for mask in range(1 << n):
        area = 0
        for i in range(n):
            if mask & (1 << i):
                a, b = tiles[i]
                area += a * b
        if area == target:
            valid_masks.append(mask)
    if not valid_masks:
        return False
    for mask in valid_masks:
        selected = []
        for i in range(n):
            if mask & (1 << i):
                selected.append(tiles[i])
        orientations = []
        for a, b in selected:
            if a == b:
                orientations.append([(a, b)])
            else:
                orientations.append([(a, b), (b, a)])
        grid = [[False] * w for _ in range(h)]
        used = [False] * len(selected)
        def first_empty():
            for r in range(h):
                for c in range(w):
                    if not grid[r][c]:
                        return (r, c)
            return None
        def dfs():
            empty = first_empty()
            if empty is None:
                return True
            r, c = empty
            for idx in range(len(selected)):
                if used[idx]:
                    continue
                for h_t, w_t in orientations[idx]:
                    if r + h_t > h or c + w_t > w:
                        continue
                    ok = True
                    for i in range(r, r + h_t):
                        for j in range(c, c + w_t):
                            if grid[i][j]:
                                ok = False
                                break
                        if not ok:
                            break
                    if not ok:
                        continue
                    for i in range(r, r + h_t):
                        for j in range(c, c + w_t):
                            grid[i][j] = True
                    used[idx] = True
                    if dfs():
                        return True
                    used[idx] = False
                    for i in range(r, r + h_t):
                        for j in range(c, c + w_t):
                            grid[i][j] = False
            return False
        if dfs():
            return True
    return False

