    def count_up_to(n):
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        @lru_cache(None)
        def dp(pos, tight, started, even, odd, mod):
            if pos == len(digits):
                return 1 if (started and even == odd and mod == 0) else 0
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                ntight = tight and (d == limit)
                nstarted = started or (d != 0)
                neven = even + (1 if (nstarted and d % 2 == 0) else 0)
                nodd = odd + (1 if (nstarted and d % 2 == 1) else 0)
                nmod = (mod * 10 + d) % k
                total += dp(pos + 1, ntight, nstarted, neven, nodd, nmod)
            return total
        return dp(0, True, False, 0, 0, 0)
    return count_up_to(high) - count_up_to(low - 1)

