def count_square_permutations(n: int, s: str) -> int:
    from collections import Counter
    target = Counter(s)
    max_val = 10**n - 1
    count = 0
    for i in range(int(max_val**0.5) + 1):
        square = i * i
        square_str = str(square).zfill(n)
        if len(square_str) > n:
            continue
        if Counter(square_str) == target:
            count += 1
    return count
